def solve(I):
    H,W=len(I),len(I[0])
    bg=max({x for r in I for x in r}, key=lambda v:sum(r.count(v) for r in I))
    # marker: color with exactly 4 occurrences forming rect corners
    mk=None
    for v in sorted({x for r in I for x in r}):
        pts=[(r,c) for r in range(H) for c in range(W) if I[r][c]==v]
        if len(pts)==4:
            rs={p[0] for p in pts}; cs={p[1] for p in pts}
            if len(rs)==2 and len(cs)==2: mk=v; br0,br1=min(rs),max(rs); cl0,cl1=min(cs),max(cs)
    out=[row[:] for row in I[br0:br1+1]]
    oh,ow=br1-br0+1,cl1-cl0+1
    bgv=I[br0][cl0+1] if False else None
    # interior colors = everything except bg and marker
    def comp(cells):
        st=set(cells); seen=set(); comps=[]
        while st:
            q=[st.pop()]; c=[]
            while q:
                r,cc=q.pop()
                if (r,cc) in seen: continue
                seen.add((r,cc)); c.append((r,cc))
                for dr in(-1,0,1):
                    for dc in(-1,0,1):
                        nr,nc=r+dr,cc+dc
                        if 0<=nr<len(I) and 0<=nc<len(I[0]) and (nr,nc) in st: st.discard((nr,nc))
            comps.append(c)
        return comps
    rel=lambda r,c:r-br0,c-cl0
    # inside components
    ins={}
    oc=[]
    for r in range(br0,br1+1):
        for c in range(cl0,cl1+1):
            if I[r][c] not in (bg,mk):
                ins.setdefault(I[r][c],[]).append((r,c))
    # outside components (whole-grid comps ignoring bg)
    allc=[(r,c) for r in range(H) for c in range(W) if I[r][c] not in (bg,mk)]
    cs_=comp(allc)
    tmpl={}
    for col,pts in ins.items():
        rr=[p[0] for p in pts]; cc=[p[1] for p in pts]
        hgt,max(w for w in [max(rr)-min(rr)+1, max(cc)-min(cc)+1])
        tmpl[col]=(max(rr)-min(rr)+1, max(cc)-min(cc)+1)
    uh=sum(tmpl.values())[0]//len(tmpl) if False else None
    # unit from consensus: assume all templates same size
    us=list(tmpl.values())[0]
    Uh=us[0]; Uw=us[1]
    # slots: inside template colors -> their bbox top-left in interior coords
    slots={}
    for col,(hgt,wid) in tmpl.items():
        pts=ins[col]; slots[col]=(min(p[0] for p in pts)-br0, min(p[1] for p in pts)-cl0)
    # outside colors grouped by component; each color's cells; use per-color representative (min row, then min col)
    outcol=set(slots)
    rem=[c_ for c_ in cs_ if any(I[r][c_]!=bg and I[r][c_]!=mk for r,c_ in [])]
    # simpler: collect outside cells per color
    ocells={}
    for r in range(H):
        for c in range(W):
            if I[r][c] not in (bg,mk) and not (br0<=r<=br1 and cl0<=c<=cl1):
                ocells.setdefault(I[r][c],[]).append((r,c))
    # reference: template color with topmost-leftmost slot
    ref=min(slots.items(), key=lambda kv:(kv[1][0],kv[1][1]))[0]
    rs_,cs_=slots[ref]
    res=[row[:] for row in out]
    # place template blocks
    for col,(hgt,wid) in tmpl.items():
        for r in range(rs_,rs_+hgt):
            for c in range(cs_,cs_+wid):
                res[r][c]=col
        rs_,cs_=slots[col]
    # place non-template colors chained by offset*(Uh,Uw) from ref slot via their nearest inside-adjacent color
    placed={ref:(rs_,cs_)}
    for col,pts in ocells.items():
        if col in slots: continue
        # find offset relative to ref using nearest same-cluster relationship: use min cell coords
        mr=min(p[0] for p in pts); mc=min(p[1] for p in pts)
        # reference color cell coords
        rp=min(p[0] for p in ocells[ref]); cp=min(p[1] for p in ocells[ref])
        dr,dc=(mr-rp)*(Uh), (mc-cp)*(Uw)
        tr,tc=rs_+dr, cs_+dc
        for r in range(tr,tr+Uh):
            for c in range(tc,tc+Uw):
                res[r][c]=col
        placed[col]=(tr,tc)
    return res

